import { ChangeDetectorRef, Component } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';

@Component({
  selector: 'mf-forms-generator',
  templateUrl: './generator.component.html',
  standalone: true,
  imports: [
    ReactiveFormsModule
  ],
  styleUrls: ['./generator.component.scss'],
})
export class GeneratorComponent {
    jsonData: any = [];
    saidaEsperada: any = {};
    saidaEsperadaString: string = "";
    meuValor: string = "string"
  
    constructor(private cdr: ChangeDetectorRef) {}
    ngOnInit(): void {
      throw new Error('Method not implemented.');
    }
  
    onChangeDynamicForm(event: Event){
      let eventData = event.target as HTMLInputElement;
      let data: any = {};
      if(eventData.id.includes('.')){
        let eventDataParts = eventData.id.split(".");
        eventDataParts.forEach((item:string, i:number) => {
          if(i === eventDataParts.length - 1){
            data[item] = eventData.value;
          }
          if(i !== 0)
          {
            data = data[item];
          }
          else{
            data = this.saidaEsperada;
          }
        })
      }
      else{
        this.saidaEsperada[eventData.id] = eventData.value;
      }
      this.saidaEsperadaString = JSON.stringify(this.saidaEsperada)
    }
  
    onTextAreaChange(event: Event){
      const value = (event.target as HTMLTextAreaElement).value;
      this.jsonData = JSON.parse(value);
      this.saidaEsperada = {};
      this.jsonData.forEach((item:any) =>{
        if(item.tipo_dado === 'string'){
          this.saidaEsperada[item.contrato] = "";
        }
        if (item.tipo_dado === 'array') {
          let subItemObjeto: any = {};
          this.saidaEsperada[item.contrato] = subItemObjeto
          item.conteudo.foreach((subItem: any) => {
            subItemObjeto[subItem.contrato] = "";
          })
        }
      })
      this.saidaEsperadaString = JSON.stringify(this.saidaEsperada, null, 2);
      console.log(this.saidaEsperadaString);
      this.meuValor = this.saidaEsperadaString;
      this.cdr.detectChanges();
    }
      
  
    form = new FormGroup({
      autoResize: new FormControl(''),
    })
}
<p>generator</p>
<div class="ids-col-4 ids-card -variant">
  <p>Digite seu JSON</p>
  <form [formGroup]="form" class="form">
    <mat-form-field>
      <textarea
        matInput
        (change)="onTextAreaChange($event)"
        class="card-width"
        autoResize
        cols="30"
        formControlName="autoResize"
      ></textarea>
    </mat-form-field>
  </form>
</div>

<div class="ids-col-4 ids-card -variant">
  <p>Seu JSON ficará assim</p>
  <pre><code>{{ saidaEsperadaString }}</code></pre>
</div>

<div class="ids-col-4 ids-col-sm-8 ids-col-md-4 ids-card -variant card-width'">
  <p>Seu formulário ficará assim</p>
  <form [formGroup]="form" autocomplete="off">
    <div *ngFor="let propriedade of jsonData">
      {{ propriedade.rotulo }}
      <div *ngIf="propriedade.tipo_dado === 'array'">
        <mat-form-field *ngFor="let item of propriedade.conteudo">
          <input
            matInput
            id="array.{{ propriedade.contrato }}.{{ item.contrato }}"
            formControlName="requiredWithHelper"
            (change)="onChangeDynamicForm($event)"
          />
        </mat-form-field>
      </div>
    </div>
  </form>
</div>
